// Groups every row by status and builds the weekly email.
// "Closed this week" = won or lost rows that have no closed_at yet. They get stamped after the email,
// so each closed quote is counted in exactly one weekly summary.
const s = $('Settings').first().json;
const tz = s.timezone;
const now = DateTime.now().setZone(tz);
const rows = $input.all().map(i => i.json).filter(r => r.request_id);

const WAITING = ['missing_info', 'ready_to_quote'];
const OPEN = ['quote_sent', 'review', 'replied'];
const WON = ['accepted', 'booking_sent', 'scheduled'];
const LOST = ['lost', 'no_reply'];

const money = v => {
  const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const fmt = n => s.currency + n.toLocaleString('en-US', { minimumFractionDigits: Number.isInteger(n) ? 0 : 2, maximumFractionDigits: 2 });
const age = r => {
  const d = DateTime.fromISO(String(r.quote_sent_at || r.received_at || ''), { zone: tz });
  return d.isValid ? Math.floor(now.diff(d, 'days').days) : null;
};
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const waiting = rows.filter(r => WAITING.includes(r.status));
const open = rows.filter(r => OPEN.includes(r.status)).map(r => ({ ...r, age: age(r) }));
const closedNow = rows.filter(r => [...WON, ...LOST].includes(r.status) && !r.closed_at);
const won = closedNow.filter(r => WON.includes(r.status));
const lost = closedNow.filter(r => LOST.includes(r.status));

const openValue = open.reduce((a, r) => a + money(r.quote_amount), 0);
const wonValue = won.reduce((a, r) => a + money(r.quote_amount), 0);
const old = open.filter(r => r.age !== null && r.age >= Number(s.old_after_days))
  .sort((a, b) => b.age - a.age);
const rate = (won.length + lost.length) ? Math.round(100 * won.length / (won.length + lost.length)) + '%' : 'no quotes closed';

const line = r => `<tr><td>${esc(r.quote_id || r.request_id)}</td><td>${esc(r.name)}</td><td>${esc(r.status)}</td><td>${r.age ?? ''} days</td><td>${r.quote_amount ? esc(fmt(money(r.quote_amount))) : ''}</td></tr>`;
const table = list => list.length
  ? `<table cellpadding="6" style="border-collapse:collapse"><tr><th align="left">Quote</th><th align="left">Customer</th><th align="left">Status</th><th align="left">Open for</th><th align="left">Amount</th></tr>${list.map(line).join('')}</table>`
  : '<p>None.</p>';

const html = `
<h2>${esc(s.business_name)}: quotes, week of ${now.toFormat('d LLL yyyy')}</h2>
<ul>
  <li><b>Open quotes:</b> ${open.length}, worth ${fmt(openValue)}</li>
  <li><b>Won since last summary:</b> ${won.length}, worth ${fmt(wonValue)}</li>
  <li><b>Lost since last summary:</b> ${lost.length}</li>
  <li><b>Close rate since last summary:</b> ${rate}</li>
  <li><b>Requests still waiting for a quote:</b> ${waiting.length}</li>
</ul>
<h3>Open for ${s.old_after_days} days or more</h3>
${table(old)}
<h3>All open quotes</h3>
${table(open.sort((a, b) => (b.age ?? 0) - (a.age ?? 0)))}
`;

return [{ json: {
  subject: `${s.business_name}: ${open.length} open quotes, ${won.length} won, ${lost.length} lost this week`,
  html,
  to_stamp: closedNow.map(r => r.request_id),
}}];
